    GetNodes();
    has_entry_mesh_transition = 1;

    for (i = 0; i < 10; ++i)
    {
        float z = (float)i;
        float z_taper = z * 0.11111111f;
        primary_samples[i].center_x =
            (float)width_cells * 0.5f - 4.0f - z_taper * 0.30000001f;
        primary_samples[i].rotation_scalar_98 = 0.0f;
